tinymce.PluginManager.add('tablatura', function(editor, url) {
    // Add a button that opens a window

    editor.ui.registry.addButton('tablatura', {
        text: 'Tab',
        tooltip: 'Inserir Tablatura',
        onAction: function() {
            // Open window
            editor.insertContent('<p class="tab">&nbsp;<span class="corda">E</span>|-------------------------&nbsp;<br />&nbsp;<span class="corda">B</span>|-------------------------<br /><span class="corda">G#</span>|-------------------------<br />&nbsp;<span class="corda">E</span>|-------------------------<br />&nbsp;<span class="corda">B</span>|-------------------------</p>');

        }
    });

});